"""Convert the attributed MCP-Injector calibrated profile into a profile-draw schedule."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import yaml

MAP = {
    "OP1_smallDelta": "small_delta",
    "OP2_randomValue": "random_value",
    "OP3_randomWrongType": "wrong_type",
    "OP4_errorMessage": "error",
    "OP5_delay": "delay",
    "OP6_dropCall": "drop_call",
}

HEADER = """\
# {title}
# Generated by `python -m mcp_fault_bench convert-paper-profile` from {source}.
# Data: MCP-Injector calibrated fault profile (fault_mode_1.json), Copyright 2026 The MCP-Injector Authors,
# licensed under CC-BY-4.0 (third_party/mcp-injector/DATA-LICENSE-CC-BY-4.0). Changes: field names mapped to
# our schedule format (type -> op + paper_type, probability -> weight, duration -> seconds); values unchanged.
# Source: Iannillo et al., "Tool-Calling LLM Agents Under Realistic MCP Faults: Scale Does Not Purchase Fault
# Tolerance", NeurIPS 2026, arXiv:2610.32555.
#
# kind: profile_draw draws ONE entry by weight on a tools/call and holds it per its persistence
# (see README "Schedule: mapping to the paper").
"""


def convert_entries(source: str) -> list[dict[str, Any]]:
    """Map each paper row to an entry; weights and probabilities are copied unchanged."""
    raw = json.loads(Path(source).read_text(encoding="utf-8"))
    entries: list[dict[str, Any]] = []
    for row in raw["fault_mode"]:
        operation = MAP.get(row["type"])
        if operation is None:
            continue
        persistence = row["persistence"]
        entry: dict[str, Any] = {"op": operation, "persistence": persistence["type"].lower(),
                                 "weight": row.get("probability", 0), "paper_type": row["type"]}
        if entry["persistence"] != "permanent":
            entry["activation_p"] = persistence.get("activation_p", 1.0)
        if entry["persistence"] == "intermittent":
            entry["deactivation_p"] = persistence.get("deactivation_p", 0.3)
        params = dict(row.get("parameters", {}))
        if "duration" in params:
            params["seconds"] = params.pop("duration")
        entry["params"] = params
        entries.append(entry)
    return entries


def _write(output: str, title: str, source: str, scope: str, entries: list[dict[str, Any]]) -> None:
    lines = [HEADER.format(title=title, source=source),
             "kind: profile_draw", "seed: 42", f"scope: {scope}",
             'tools: ["*"]' + ("  # the arena passes --target <tool> per (task, rep)" if scope == "tools" else ""),
             f"source: {source}", "entries:"]
    for entry in entries:
        lines.append("  - " + yaml.safe_dump(entry, default_flow_style=True, sort_keys=False, width=1000).strip())
    Path(output).write_text("\n".join(lines) + "\n", encoding="utf-8")


def convert(source: str, output: str, scoped_output: str | None = None) -> None:
    """Write the global profile and, optionally, the tool-scoped variant."""
    entries = convert_entries(source)
    _write(output, "Paper OPP profile (global scope)", source, "global", entries)
    if scoped_output:
        _write(scoped_output, "Paper OPP profile, scoped to one target tool per run (our addition)",
               source, "tools", entries)
